package org.example.idf_service.web; import jakarta.validation.Valid; import org.example.idf_service.dto.TransactionRequest; import org.example.idf_service.service.TransactionService; import org.springframework.http.*; import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/api/transactions") public class TransactionController { private final TransactionService service; public TransactionController(TransactionService s){service=s;} @PostMapping public ResponseEntity<Void> create(@Valid @RequestBody TransactionRequest request){service.register(request);return ResponseEntity.status(HttpStatus.CREATED).build();} }
